int[] a = { 1, 3, 5, 7, 9, 11 };
int lo = 0, hi = a.Length - 1, steps = 0;
while (lo <= hi)
{
    int mid = lo + (hi - lo) / 2;
    steps++;
    if (a[mid] == 7) break;
    if (a[mid] < 7) lo = mid + 1; else hi = mid - 1;
}
Console.WriteLine(steps);

